mb_strlen($o) > 1) { $t = $o; $o = $i; $i = $f; $f = $t; } switch ($format) { case 'fullfio': return $f. ($i ? ' '.$i : ''). ($o ? ' '.$o : ''); case 'fio': return $f. ($i ? ' '.mb_substr($i, 0, 1).'.' : ''). ($o ? mb_substr($o, 0, 1).'.' : ''); case 'iof': return ($i ? mb_substr($i, 0, 1).'.' : ''). ($o ? mb_substr($o, 0, 1).'.' : ''). ($i || $o ? ' ' : '').$f; } } return $inputFio; } function generateUUID(?int $len = null, ?int $radix = null, bool $toLowerCase = false): string { $chars = str_split('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'); $uuid = []; $radix = $radix || count($chars); if ($len) { for ($i = 0; $i < $len; $i++) { $uuid[$i] = $chars[0 | random() * $radix]; } } else { $uuid[8] = $uuid[13] = $uuid[18] = $uuid[23] = '-'; $uuid[14] = '4'; for ($i = 0; $i < 36; $i++) { if (!array_key_exists($i, $uuid)) { $r = 0 | (int)(random() * 16); $uuid[$i] = $chars[($i == 19) ? ($r & 0x3) | 0x8 : $r]; } } } ksort($uuid); $result = implode('', $uuid); return $toLowerCase ? strtolower($result) : $result; } function number($value) { return ($value == (int) $value) ? (int) $value : (float) $value; } function udate ($strFormat = 'u', $uTimeStamp = null) { if (is_null($uTimeStamp)) { $uTimeStamp = microtime(true); } $dtTimeStamp = floor($uTimeStamp); $intMilliseconds = round(($uTimeStamp - $dtTimeStamp) * 1000000); $strMilliseconds = str_pad($intMilliseconds, 6, '0', STR_PAD_LEFT); return date(preg_replace('`(?<!\\\\)u`', $strMilliseconds, $strFormat), $dtTimeStamp); } function rcppRun($module, $fn, $params) { $config = getSessionValue('config'); $appConfig = getSessionValue('appConfig'); $logFile = "rcppRun"; if (empty($appConfig['mapBin'])) { throw new \Exception('В конфигурации "' . $config . '" не указан параметр "mapBin" с каталогом содержащим файл "map.exe"!'); } $mapBin = realpath($appConfig['mapBin']); $mapExe = $mapBin . '\\map.exe'; if (!file_exists($mapExe)) { throw new \Exception('Файл "' . $mapExe . '" не существует!'); } $connect = empty($appConfig['connect']) ? '' : " -db \"{$appConfig['connect']}\""; $cmd = "\"$mapExe\"$connect -rcpprun " . "\"" . mb_convert_encoding($module, 'CP1251', mb_detect_encoding($module)) . "\" " . "\"" . mb_convert_encoding($fn, 'CP1251', mb_detect_encoding($fn)) . "\"" . (empty($params) ? "" : " " . implode(' ', $params)); $execStr = "$cmd"; app_log("Старт расчета $execStr", 0, $logFile); chdir($mapBin); $handle = popen($execStr, 'r'); if ($handle === false) { throw new \Exception("Неизвестная ошибка при вызове расчета, строка запуска: $execStr"); } $result = pclose($handle); if (empty($result)) { app_log("Расчет успешно выполнен.", 0, $logFile); } else { $error = "Ошибка выполнения расчета [$result]!"; app_log($error, 2, $logFile); throw new \Exception($error); } return $result; } function cloneFn ($array) { return safe_json_decode(json_encode($array)); } function random () { return (float)rand()/(float)getrandmax(); } function humanFileSize ($bytes, $decimals = 2) { $factor = floor((safe_strlen($bytes) - 1) / 3); if ($factor > 0) $sz = 'KMGT'; return sprintf("%.{$decimals}f", $bytes / pow(1024, $factor)) . @$sz[$factor - 1] . 'B'; } function checkPermisson ($permission, $superuser = 'superuser') { $roles = getSessionValue('roles'); if (empty($roles)) { return false; } if (is_string($roles)) { $roles = ',' . $roles . ','; return safe_strpos($roles, ',' . $permission . ',') !== false || safe_strpos($roles, ',' . $superuser . ',') !== false; } else if (is_array($roles)) { return isset($roles[$permission]) || isset($roles[$superuser]); } else { return false; } } function checkPermissons ($permissions, $superuser = 'superuser') { $a = safe_explode(',', $permissions); foreach ($a as $v) { if (checkPermisson($v, $superuser)) { return true; } } return false; } function executeCmd ($command, &$exitcode = null) { $command .= ' 2>&1'; if (($handle = popen($command, 'r')) === false) { throw new \Exception("Ошибка запуска команды \"$command\""); } $log = ''; while (!feof($handle)) { $log .= fread($handle, 4096); } $exitcode = pclose($handle); if (mb_detect_encoding($log, 'UTF-8', true) === false) { $log = mb_convert_encoding($log, 'UTF-8', 'CP1251'); } return $log; } function compareVersions ($a, $b, $limit = PHP_INT_MAX) { $a = safe_explode('.', $a); $b = safe_explode('.', $b); for ($i = 0; $i < count($a); $i++) { if ($i >= $limit) return 0; if ($i >= count($b) || (int)$a[$i] > (int)$b[$i]) return 1; if ((int)$a[$i] < (int)$b[$i]) return -1; } if (count($b) > count($a)) return -1; return 0; } function createIniString (&$out, $array) { foreach ($array as $key => $value) { if (is_array($value)) { $out .= "[{$key}]" . PHP_EOL; createIniString($out, $value); } else { $out .= "{$key}={$value}" . PHP_EOL; } } } function isVowel ($symbol) { static $vowelSymbols = ['а'=>1, 'е'=>1, 'ё'=>1, 'и'=>1, 'о'=>1, 'у'=>1, 'ю'=>1, 'я'=>1]; return isset($vowelSymbols[mb_strtolower($symbol)]); } function detectSex ($fio) { $arr = preg_split('~[^\p{L}\p{N}\']+~u', $fio); if (count($arr) >= 3 && isVowel(mb_substr($arr[2], -1))) return 1; return 0; } function removeBOM(string $str): string { if (substr($str, 0, 3) == pack('CCC', 0xef, 0xbb, 0xbf)) { $str = substr($str, 3); } return $str; } function base64url_encode(string $data): string { return rtrim(strtr(base64_encode($data), '+/', '-_'), '='); } function base64url_decode(string $data): string { return base64_decode(str_pad(strtr($data, '-_', '+/'), strlen($data) % 4, '=', STR_PAD_RIGHT)); } function cleanNonprintableChars($value): string { if (is_string($value)) { return preg_replace('/[\x{200B}-\x{200D}\x{FEFF}]/u', '', $value); } return $value; }